import type { ViewTransitionClass } from 'react'

/**
 * Maps the transition types set by `<Link transitionTypes={[...]}>` onto
 * directional slide classes, so a page slides left on the way forward and right
 * on the way back.
 *
 * `default: 'none'` keeps untyped transitions — browser back/forward, a
 * `router.refresh()`, or a Suspense reveal inside the page — from sliding the
 * whole page sideways.
 */
export const navDirection: ViewTransitionClass = {
  'nav-forward': 'nav-forward',
  'nav-back': 'nav-back',
  default: 'none',
}

/** Shared-element name pairing a grid thumbnail with its detail hero. */
export function productImageName(slug: string) {
  return `product-image-${slug}`
}

