import { Suspense, ViewTransition } from 'react'
import { ProductGrid } from './ProductGrid'
import { ProductGridSkeleton } from './ProductSkeleton'
import { navDirection } from './transitions'

export default function Home() {
  return (
    // The directional wrapper lives in the page, not the layout: layouts persist
    // across navigations, so enter/exit would never fire there.
    <ViewTransition enter={navDirection} exit={navDirection} default="none">
      <main>
        <h1>Products</h1>
        <Suspense
          fallback={
            <ViewTransition exit="slide-down" default="none">
              <ProductGridSkeleton />
            </ViewTransition>
          }
        >
          <ViewTransition enter="slide-up" default="none">
            <ProductGrid />
          </ViewTransition>
        </Suspense>
      </main>
    </ViewTransition>
  )
}

