/* ---------------------------------------------------------------------------
   View transitions

   Timing is deliberately asymmetric: old content leaves quickly so it stops
   competing for attention, new content arrives more gently and waits for the
   exit to finish before it becomes visible.
   --------------------------------------------------------------------------- */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* The transition overlay swallows pointer events by default, so clicks during
   an animation are lost. Let them through to the live page. */
::view-transition {
  pointer-events: none;
}

/* Shared element: grid thumbnail <-> detail hero (share="morph").
   The browser animates size and position on its own; the blur only hides
   pixel-level interpolation artifacts mid-flight. */
::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
}
::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}

/* Suspense reveal: the skeleton drops away, the real content rises in. */
::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}
::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}

/* Directional navigation: forward moves content left, back moves it right.
   60px is enough to read as direction without asking the user to track a
   fast-moving element across the viewport. */
::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}
::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    var(--duration-exit) ease-in both fade reverse,
    var(--duration-move) ease-in-out both slide reverse;
}
::view-transition-new(.nav-back) {
  --slide-offset: -60px;
  animation:
    var(--duration-enter) ease-out var(--duration-exit) both fade,
    var(--duration-move) ease-in-out both slide;
}

@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes slide {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

